pip list 2>/dev/null | grep -i -E "transformers|torch|sentence|ollama|deepseek|numpy|pandas" ; echo "---checking imports---"; python3 -c "
import importlib
for m in ['sentence_transformers','torch','langchain_huggingface','langchain_chroma','langchain_openai','chromadb','langchain_core']:
    try:
        mod = importlib.import_module(m)
        print('OK', m, getattr(mod,'__version__','?'))
    except Exception as e:
        print('FAIL', m, type(e).__name__, e)
"
